def comb_sort(arr):
    n = len(arr)
    gap = twin_gap(arr)

    while gap > 1 or n > 1:
        gap = twin_gap(arr)
        swapped = False

        for i in range(0, n-gap):
            if arr[i] > arr[i+gap]:
                arr[i], arr[i+gap] = arr[i+gap], arr[i]
                swapped = True

        if not swapped:
            break

    return arr

